parameters.jsCode:
const tickets = $('On form submission').all();
const respuestas = $input.all();

const URGENCIAS = ['Alta', 'Media', 'Baja'];
const CATEGORIAS = ['Pagos', 'Envios', 'Producto', 'Soporte'];
const DEPARTAMENTOS = ['Facturacion', 'Logistica', 'Atencion al Cliente'];

// El texto del formulario y de la IA no es de fiar: se neutralizan las menciones (@everyone),
// se quitan los saltos de línea y se limita la longitud (Discord admite 2000 caracteres por mensaje).
const limpiar = (valor, max) => {
  const texto = String(valor ?? '').replace(/@/g, '@\u200b').replace(/\s+/g, ' ').trim();
  return texto.length > max ? texto.slice(0, max - 1) + '…' : texto;
};

// Compara sin tildes ni mayúsculas ("Envíos" == "envios") y devuelve el valor oficial.
const normalizar = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const elegir = (valor, permitidos) => permitidos.find((p) => normalizar(p) === normalizar(valor));

// Un ticket por cada respuesta de la IA (en producción llega uno; al probar con varios, todos).
return respuestas.map((entrada, i) => {
  const ticket = tickets[i].json;
  const respuesta = entrada.json;

  // 1) Leer la respuesta de la IA sin que un fallo rompa el flujo
  let ia = null;
  let motivo = '';
  try {
    const contenido = respuesta?.choices?.[0]?.message?.content;
    if (!contenido) throw new Error('sin contenido');
    ia = JSON.parse(contenido);
    if (typeof ia !== 'object' || ia === null || Array.isArray(ia)) throw new Error('formato inesperado');
  } catch (e) {
    ia = null;
    motivo = 'No se pudo leer la respuesta de la IA';
  }

  // 2) Si la urgencia no es válida, se trata como ALTA y se marca para revisión manual:
  //    ante la duda, un ticket nunca debe pasar desapercibido.
  const urgencia = ia ? elegir(ia.urgencia, URGENCIAS) : undefined;
  const revisionManual = !urgencia;
  if (revisionManual && !motivo) motivo = 'Urgencia no válida en la respuesta de la IA';

  const salida = {
    cliente: limpiar(ticket.Cliente, 80),
    email: limpiar(ticket.Email, 100),
    pedido: limpiar(ticket['Numero de pedido'] || 'No indicado', 40),
    problema: limpiar(ticket.Problema, 400),
    fecha: ticket.submittedAt,
    categoria: (ia && elegir(ia.categoria, CATEGORIAS)) || 'Sin clasificar',
    departamento: (ia && elegir(ia.departamento, DEPARTAMENTOS)) || 'Atencion al Cliente',
    urgencia: urgencia || 'Alta',
    resumen: ia ? limpiar(ia.resumen, 150) : '',
    respuesta_cliente: ia ? limpiar(ia.respuesta_cliente, 600) : '',
    revision_manual: revisionManual,
  };

  if (revisionManual) {
    salida.resumen = '⚠️ ' + motivo + ': revisar a mano.';
    salida.respuesta_cliente = '(sin borrador)';
  }

  return { json: salida };
});

